/* ============================================
   AI BUTTON
   The AI entry point: a solid field pushed past
   the page floor (bright white in light, true
   black in dark), slowly rotating gradient ring,
   soft glow of the same gradient haloing the
   edge. The ring is the system's "a model
   answers here" signal — ordinary actions keep
   the flat action teal.
   ============================================ */

/* The rotation animates a registered custom property: a conic gradient's
   angle cannot tween otherwise. Browsers without @property render the ring
   at its initial angle, static — a correct, quieter fallback. */
@property --ds-ai-button-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

/* Base */
.ds-ai-button {
  /* Layout */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-200);

  /* Spacing — matches Button so the two sit on one control scale */
  padding: var(--padding-200) var(--padding-500);

  /* Buttons are always pill-shaped (design.md invariant) */
  border-radius: var(--radius-pill);

  /* Typography — the clickable-control face, same as Button */
  font-family: var(--font-paragraph-emphasis-family);
  font-weight: var(--font-paragraph-emphasis-weight);
  font-size: var(--font-paragraph-emphasis-size);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  text-align: center;
  /* A pill's label never wraps — a squeezed layout shortens around the
     button, it doesn't fold the silhouette into two lines. */
  white-space: nowrap;

  /* The field is the theme's extreme surface — brighter than the light page,
     deeper than the dark one — so the pill stands off whatever it floats
     over. The opaque fill also keeps the glow at the edges: the ::after
     escapes behind the button (negative z-index, no stacking context here),
     so it reads as a halo, not a tint. */
  background: var(--color-ai-button-bg);
  color: var(--color-text-primary);

  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);

  /* Reset */
  cursor: pointer;
  border: none;
  text-decoration: none;
}

/* The gradient ring: a conic gradient painted across the whole button, then
   masked to the border band (two fills, exclude-composited, inset by the
   border width). The gradient repeats back to its start colour so the seam
   at 360° is invisible while it turns. */
.ds-ai-button::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: var(--border-050);
  background: conic-gradient(
    from var(--ds-ai-button-angle),
    var(--color-ai-gradient-start),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-end),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-start)
  );
  /* Standard properties only — the build pipeline prefixes per its browser
     targets, and hand-written -webkit- duplicates confuse its merging. */
  /* ds-allow(color): mask luminance keying — the #fff paints alpha coverage
     for mask-composite, not a theme colour */
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
  /* The entry shares the glow's corner origin (a fraction chosen by eye)
     and lands a --motion-duration-fast beat after the bloom starts. */
  transform-origin: 90% 90%;
  /* ds-allow(motion): ambient signature rotation, tuned by eye — deliberately
     far slower than the interaction-scale motion tokens. The 21s loop is
     three uneven turns (the keyframes own the cadence), so the pace swells
     and settles instead of ticking round like a clock. The second animation
     is the one-shot entry — opacity/transform only, so the two compose. */
  animation:
    ds-ai-button-turn 21s var(--motion-ease-emphasized) infinite,
    ds-ai-button-enter-ring var(--motion-duration-slower) var(--motion-ease-entrance) var(--motion-duration-fast) backwards;
}

/* The glow: the same gradient, blurred behind the button at low opacity.
   A colour effect, not an elevation shadow — depth stays token-owned. */
.ds-ai-button::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(
    from var(--ds-ai-button-angle),
    var(--color-ai-gradient-start),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-end),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-start)
  );
  /* The glow's spread; a length with no token family, chosen by eye. */
  --ds-ai-button-glow: 14px;
  filter: blur(var(--ds-ai-button-glow));
  opacity: 0.3;
  z-index: -1;
  pointer-events: none;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
  /* The bloom grows out of the bottom-right corner — a fraction chosen by
     eye, matching the ring's origin. */
  transform-origin: 90% 90%;
  /* ds-allow(motion): same ambient rotation as the ring, kept in phase;
     the second animation is the one-shot entry bloom */
  animation:
    ds-ai-button-turn 21s var(--motion-ease-emphasized) infinite,
    ds-ai-button-enter-glow var(--motion-duration-slower) var(--motion-ease-entrance) backwards;
}

/* Three full turns with unevenly spaced stops, eased per segment: the ring
   drifts, surges, and settles rather than rotating at one mechanical rate.
   The angles are turn fractions tuned by eye; the loop ends on a whole
   turn (1080deg), so the repeating gradient makes the wrap seamless and
   the average pace stays one turn per 7s. */
@keyframes ds-ai-button-turn {
  0% {
    --ds-ai-button-angle: 0deg;
  }
  14% {
    --ds-ai-button-angle: 168deg;
  }
  31% {
    --ds-ai-button-angle: 306deg;
  }
  46% {
    --ds-ai-button-angle: 570deg;
  }
  62% {
    --ds-ai-button-angle: 690deg;
  }
  79% {
    --ds-ai-button-angle: 936deg;
  }
  100% {
    --ds-ai-button-angle: 1080deg;
  }
}

/* The entry: on mount the glow blooms out of the bottom-right corner while
   the ring fades up into place a beat behind it — the button lights rather
   than arriving at full strength. From-only keyframes: each settles onto
   the element's base styles, so hover and the ambient turn take over with
   nothing filled forward. */
@keyframes ds-ai-button-enter-ring {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
}

@keyframes ds-ai-button-enter-glow {
  from {
    opacity: 0;
    transform: scale(0.35);
  }
}

/* Icon rides the icon-size scale */
.ds-ai-button__icon {
  --icon-size: var(--icon-size-600);
  line-height: 1;
}

/* States */
.ds-ai-button:hover::after {
  opacity: 0.55;
}

.ds-ai-button:focus-visible {
  outline: var(--border-050) solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-ai-button--disabled,
.ds-ai-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-ai-button--disabled::before,
.ds-ai-button--disabled::after,
.ds-ai-button:disabled::before,
.ds-ai-button:disabled::after {
  /* The turn (first in the list) pauses; the one-shot entry still runs to
     completion, or a button disabled from birth would freeze mid-entrance
     with an invisible ring. */
  animation-play-state: paused, running;
}

/* Sizes */
.ds-ai-button--compact {
  padding: var(--padding-150) var(--padding-300);
  font-size: var(--font-paragraph-sm-emphasis-size);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-ai-button--compact .ds-ai-button__icon {
  --icon-size: var(--icon-size-500);
}

/* Reduced motion: the ring and glow stay, the turning stops. */
@media (prefers-reduced-motion: reduce) {
  .ds-ai-button::before,
  .ds-ai-button::after {
    animation: none;
  }
}

/* ============================================
   THE SUMMARY PANEL
   AiButton's TLDR surface: a frosted glass card
   summoned above (or below) the button. The
   button and panel share one hover zone — the
   host — and the AI gradient sweeps once around
   the panel's border as it opens, then fades to
   the ordinary container border.
   ============================================ */

.ds-ai-button-host {
  position: relative;
  display: inline-flex;
}

/* The button acknowledges the panel's arrival with one gentle pulse. */
.ds-ai-button-host--open .ds-ai-button {
  animation: ds-ai-button-acknowledge var(--motion-duration-deliberate) var(--motion-ease-spring) both;
}

@keyframes ds-ai-button-acknowledge {
  from {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
  to {
    transform: scale(1);
  }
}

.ds-ai-button__summary {
  position: absolute;
  right: 0;
  z-index: 1;
  /* Component-local lengths, chosen by eye like the button's glow: a
     readable measure, capped so a phone viewport keeps its margins. */
  --ds-ai-summary-width: 340px;
  --ds-ai-summary-viewport-margin: 40px;
  width: min(var(--ds-ai-summary-width), calc(100vw - var(--ds-ai-summary-viewport-margin)));

  display: flex;
  flex-direction: column;
  gap: var(--gap-200);

  padding: var(--padding-500);
  border-radius: var(--radius-600);
  /* ds-allow(color): the light glass token reads solid on a floating card;
     thinned so the page shows through the frost */
  background: color-mix(in srgb, var(--color-bg-glass) 62%, transparent);
  /* The frost: heavier than the 24px glass pairing so the blur reads
     unmistakably over imagery — a component-local effect length, chosen by
     eye. Standard property only: the build pipeline prefixes it, and a
     hand-written -webkit- duplicate makes its merging drop the declaration. */
  --ds-ai-summary-frost: 36px;
  backdrop-filter: blur(var(--ds-ai-summary-frost)) saturate(1.5);
  border: var(--border-025) solid var(--color-bg-container-border);
  box-shadow: var(--shadow-floating);

  /* Mounted but resting: the closed state mirrors the pop's `from`, so
     leaving transitions back down the same path the entrance sprang up.
     visibility keeps the hidden panel out of the accessibility tree and
     the tab order, the way HoverCard hides. */
  visibility: hidden;
  opacity: 0;
  transform: translateY(10px) scale(0.9);
  transition:
    opacity var(--motion-duration-fast) var(--motion-ease-standard),
    transform var(--motion-duration-fast) var(--motion-ease-standard),
    visibility var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-ai-button-host--open .ds-ai-button__summary {
  visibility: visible;
  opacity: 1;
  transform: none;
  animation: ds-ai-summary-pop var(--motion-duration-deliberate) var(--motion-ease-entrance) both;
}

/* Dark glass is already translucent; thinning it further puts body text
   straight onto whatever bright imagery sits beneath. */
[data-theme='dark'] .ds-ai-button__summary {
  background: var(--color-bg-glass);
}

/* Placement: the panel grows out of the button, so its transform origin
   points back at the button's side of the gap. */
.ds-ai-button-host--top .ds-ai-button__summary {
  bottom: calc(100% + var(--gap-200));
  transform-origin: calc(100% - 60px) calc(100% + 40px);
}

.ds-ai-button-host--bottom .ds-ai-button__summary {
  top: calc(100% + var(--gap-200));
  transform-origin: calc(100% - 60px) -40px;
  transform: translateY(-10px) scale(0.9);
}

.ds-ai-button-host--bottom.ds-ai-button-host--open .ds-ai-button__summary {
  transform: none;
}

@keyframes ds-ai-summary-pop {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.9);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.ds-ai-button-host--bottom.ds-ai-button-host--open .ds-ai-button__summary {
  animation-name: ds-ai-summary-pop-down;
}

@keyframes ds-ai-summary-pop-down {
  from {
    opacity: 0;
    transform: translateY(-10px) scale(0.9);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* The opening signature: the AI gradient sweeps once around the whole
   border — the button's masked conic ring, run as a single swoosh — then
   fades away, leaving the regular border. The rotation animates a
   registered custom property; without @property support the ring still
   fades in and out, just without turning. */
@property --ds-ai-summary-ring-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

.ds-ai-button__summary::before {
  content: '';
  position: absolute;
  inset: calc(-1 * var(--border-025));
  border-radius: var(--radius-600);
  padding: var(--border-050);
  background: conic-gradient(
    from var(--ds-ai-summary-ring-angle),
    var(--color-ai-gradient-start),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-end),
    var(--color-ai-gradient-mid),
    var(--color-ai-gradient-start)
  );
  /* ds-allow(color): mask luminance keying — the #fff paints alpha coverage
     for mask-composite, not a theme colour */
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
  opacity: 0;
}

.ds-ai-button-host--open .ds-ai-button__summary::before {
  /* ds-allow(motion): one-shot signature sweep timed to the panel's
     entrance, tuned by eye — it runs once, then the border is ordinary */
  animation: ds-ai-summary-ring 1500ms var(--motion-ease-standard) both;
  animation-delay: 100ms;
}

@keyframes ds-ai-summary-ring {
  from {
    --ds-ai-summary-ring-angle: 0deg;
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  65% {
    opacity: 1;
  }
  to {
    --ds-ai-summary-ring-angle: 360deg;
    opacity: 0;
  }
}

/* The content settles a beat behind the surface — each row fades up in
   sequence, so the panel and its contents arrive as one gesture. */
.ds-ai-button-host--open .ds-ai-button__summary-meta,
.ds-ai-button-host--open .ds-ai-button__summary-title,
.ds-ai-button-host--open .ds-ai-button__summary-text,
.ds-ai-button-host--open .ds-ai-button__summary-actions {
  animation: ds-ai-summary-rise var(--motion-duration-slow) var(--motion-ease-entrance) both;
}

/* ds-allow(motion): stagger offsets between rows, tuned by eye — the paced
   durations themselves are the motion tokens above */
.ds-ai-button-host--open .ds-ai-button__summary-meta { animation-delay: 80ms; }
.ds-ai-button-host--open .ds-ai-button__summary-title { animation-delay: 130ms; }
.ds-ai-button-host--open .ds-ai-button__summary-text { animation-delay: 180ms; }
.ds-ai-button-host--open .ds-ai-button__summary-actions { animation-delay: 230ms; }

@keyframes ds-ai-summary-rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.ds-ai-button__summary-dismiss {
  position: absolute;
  top: var(--gap-200);
  right: var(--gap-200);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* Icon-button hit target — a component-local size, chosen by eye. */
  --ds-ai-summary-dismiss-size: 28px;
  width: var(--ds-ai-summary-dismiss-size);
  height: var(--ds-ai-summary-dismiss-size);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-text-secondary);
  cursor: pointer;
}

.ds-ai-button__summary-dismiss:hover {
  background: var(--color-bg-container-secondary);
  color: var(--color-text-primary);
}

.ds-ai-button__summary-dismiss .material-symbols-rounded {
  font-size: var(--icon-size-500);
}

.ds-ai-button__summary-meta {
  display: flex;
  align-items: baseline;
  gap: var(--gap-200);
  /* Keeps the row clear of the dismiss button in the corner. */
  padding-right: var(--gap-1000);
}

.ds-ai-button__summary-overline {
  font-family: var(--font-overline-family);
  font-size: var(--font-overline-size);
  font-weight: var(--font-overline-weight);
  line-height: var(--font-overline-line-height);
  letter-spacing: var(--font-overline-letter-spacing);
  text-transform: uppercase;
  color: var(--color-text-secondary);
}

.ds-ai-button__summary-caption {
  font-family: var(--font-family-primary);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
}

.ds-ai-button__summary-title {
  /* Long titles wrap short of the dismiss corner. */
  padding-right: var(--gap-500);
  font-family: var(--font-family-primary);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  color: var(--color-text-primary);
}

.ds-ai-button__summary-text {
  display: block;
  font-family: var(--font-family-primary);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  color: var(--color-text-secondary);
  /* Seats the ghost/reveal stack below. */
  position: relative;
}

/* During the type-out, an invisible ghost of the finished text sizes the
   container and the stream paints over it — the panel takes its final
   height the moment "generation" completes, and a short summary reserves
   nothing it won't use. */
.ds-ai-button__summary-text-ghost {
  visibility: hidden;
}

.ds-ai-button__summary-text-reveal {
  position: absolute;
  inset: 0;
}

.ds-ai-button__summary-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--gap-200);
  margin-top: var(--gap-100);
}

@media (prefers-reduced-motion: reduce) {
  .ds-ai-button-host--open .ds-ai-button,
  .ds-ai-button-host--open .ds-ai-button__summary,
  .ds-ai-button-host--open .ds-ai-button__summary::before,
  .ds-ai-button-host--open .ds-ai-button__summary-meta,
  .ds-ai-button-host--open .ds-ai-button__summary-title,
  .ds-ai-button-host--open .ds-ai-button__summary-text,
  .ds-ai-button-host--open .ds-ai-button__summary-actions {
    animation: none;
  }

  .ds-ai-button__summary {
    transition: none;
  }
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { PromptSuggestions, type PromptSuggestion } from '../PromptSuggestions/PromptSuggestions';
import { Skeleton } from '../Skeleton/Skeleton';
import { StreamingText } from '../StreamingText/StreamingText';
import {
  MOTION_HOVER_SHOW_DELAY_MS,
  MOTION_HOVER_EXIT_GRACE_MS,
  MOTION_SUMMARY_THINK_MS,
  MOTION_SUMMARY_REVEAL_MS,
} from '../../tokens/motion';
import './AiButton.css';
import '../../fonts/material-symbols.css';

/** The content of AiButton's summary panel. */
export interface AiButtonSummary {
  /** Overline label above the title. */
  overline?: string;
  /** Title line — usually the page or subject being summarized. */
  title: string;
  /** Small caption beside the overline, e.g. a reading time. */
  caption?: string;
  /** The pre-written summary the panel reveals. */
  text: string;
  /** Prompt chips under the summary; a tap reports through `onSummarySuggestion`. */
  suggestions?: PromptSuggestion[];
}

/** Props owned by AiButton itself — everything else falls through to the DOM node. */
type AiButtonOwnProps = {
  /** Button text content */
  label?: string;
  /** Leading icon — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Button size */
  size?: 'default' | 'compact';
  /** Whether the button is disabled */
  disabled?: boolean;
  /** Optional href — renders as <a> instead of <button> */
  href?: string;
  /** Optional target attribute for links */
  target?: string;
  /** Optional rel attribute for links */
  rel?: string;
  /**
   * A TLDR panel the button can summon: overline, title, a pre-written
   * summary revealed through a skeleton beat and a typed stream (once per
   * mount — later openings show it instantly, as if cached), and optional
   * prompt chips. Hovering the button opens it after the standard hover
   * delay; the pointer keeps it alive anywhere over the button or panel,
   * and it hides a grace period after leaving both. Omit for the plain
   * button.
   */
  summary?: AiButtonSummary;
  /** Which side of the button the summary panel opens on. */
  summaryPlacement?: 'top' | 'bottom';
  /**
   * Holds the summary panel open regardless of hover — for callers that
   * reveal it on their own signal (scroll depth, dwell). Hover mechanics
   * still run when it flips back off.
   */
  summaryPinned?: boolean;
  /** Fires when the panel's dismiss button is pressed. The panel closes itself either way; hovering away and back re-summons it. */
  onSummaryDismiss?: () => void;
  /** Fires with the tapped summary suggestion's `id`. */
  onSummarySuggestion?: (id: string) => void;
  /** Additional CSS classes */
  className?: string;
};

export interface AiButtonProps
  extends AiButtonOwnProps,
    Omit<React.ComponentPropsWithoutRef<'button'>, keyof AiButtonOwnProps | 'type'> {}

/**
 * The AI entry point. Icon and label on a solid field pushed past the page
 * floor (`--color-ai-button-bg` — bright white in light, true black in dark),
 * ringed by the AI gradient (`--color-ai-gradient-*`) rotating slowly, with a
 * soft glow of the same gradient haloing the edge. The treatment is the design system's signal
 * for "a model answers here": ordinary actions keep the flat action teal,
 * and this ring is reserved for AI surfaces so neither affordance dilutes
 * the other.
 *
 * With `summary`, the button can also summon a TLDR panel — a glass card
 * that opens above (or below) it on hover or when pinned, fakes a one-time
 * generation beat (skeleton, then a typed reveal), and offers prompt chips.
 * The panel and button share one hover zone, and the gradient sweeps once
 * around the panel's border as it opens.
 *
 * Renders a `<button>`, or an `<a>` when `href` is supplied. Forwards a ref
 * to whichever element it renders, and spreads unrecognised props onto it.
 * The rotation pauses under `prefers-reduced-motion`; the ring and glow stay.
 */
export const AiButton = React.forwardRef<HTMLButtonElement | HTMLAnchorElement, AiButtonProps>(
  (
    {
      label = 'Ask AI',
      icon = 'auto_awesome',
      size = 'default',
      disabled,
      href,
      target,
      rel,
      summary,
      summaryPlacement = 'top',
      summaryPinned = false,
      onSummaryDismiss,
      onSummarySuggestion,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-ai-button';

    const [hoverOpen, setHoverOpen] = useState(false);
    const [dismissed, setDismissed] = useState(false);
    const [phase, setPhase] = useState<'skeleton' | 'typing' | 'cached'>('skeleton');
    const generated = useRef(false);
    const showTimer = useRef<number | null>(null);
    const hideTimer = useRef<number | null>(null);

    const panelOpen =
      Boolean(summary) && !disabled && !dismissed && (summaryPinned || hoverOpen);

    /* The fake generation runs once per mount; every later opening shows
       the text instantly, as if cached. */
    useEffect(() => {
      if (!panelOpen) return;
      if (generated.current) {
        setPhase('cached');
        return;
      }
      setPhase('skeleton');
      const t = window.setTimeout(() => {
        generated.current = true;
        setPhase('typing');
      }, MOTION_SUMMARY_THINK_MS);
      return () => window.clearTimeout(t);
    }, [panelOpen]);

    useEffect(
      () => () => {
        if (showTimer.current) window.clearTimeout(showTimer.current);
        if (hideTimer.current) window.clearTimeout(hideTimer.current);
      },
      [],
    );

    /* One hover zone: the host wraps the button and the panel, so pointer
       travel between them never leaves it. Entering cancels a pending hide;
       leaving hides after the exit grace. */
    const hostEnter = () => {
      if (hideTimer.current) {
        window.clearTimeout(hideTimer.current);
        hideTimer.current = null;
      }
      if (!hoverOpen && !showTimer.current) {
        showTimer.current = window.setTimeout(() => {
          showTimer.current = null;
          setHoverOpen(true);
        }, MOTION_HOVER_SHOW_DELAY_MS);
      }
    };
    const hostLeave = () => {
      /* Leaving re-arms a dismissed panel: the X closes it for this visit,
         the next hover summons it fresh. */
      setDismissed(false);
      if (showTimer.current) {
        window.clearTimeout(showTimer.current);
        showTimer.current = null;
      }
      if (hoverOpen && !hideTimer.current) {
        hideTimer.current = window.setTimeout(() => {
          hideTimer.current = null;
          setHoverOpen(false);
        }, MOTION_HOVER_EXIT_GRACE_MS);
      }
    };

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      disabled && `${baseClass}--disabled`,
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const content = (
      <>
        {icon &&
          (typeof icon === 'string' ? (
            <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
              {icon}
            </span>
          ) : (
            <span className={`${baseClass}__icon`} aria-hidden="true">
              {icon}
            </span>
          ))}
        <span className={`${baseClass}__text`}>{label}</span>
      </>
    );

    const control =
      href && !disabled ? (
        <a
          {...(rest as React.ComponentPropsWithoutRef<'a'>)}
          ref={ref as React.Ref<HTMLAnchorElement>}
          className={classes}
          href={href}
          target={target}
          rel={rel}
        >
          {content}
        </a>
      ) : (
        <button
          {...rest}
          ref={ref as React.Ref<HTMLButtonElement>}
          type="button"
          className={classes}
          disabled={disabled}
        >
          {content}
        </button>
      );

    if (!summary) return control;

    const panelClass = `${baseClass}__summary`;

    return (
      <div
        className={[
          `${baseClass}-host`,
          `${baseClass}-host--${summaryPlacement}`,
          panelOpen && `${baseClass}-host--open`,
        ]
          .filter(Boolean)
          .join(' ')}
        onMouseEnter={hostEnter}
        onMouseLeave={hostLeave}
      >
        {control}
        {/* Mounted whenever a summary exists, shown by the host's --open
            class, so closing can ease out the way HoverCard does —
            visibility keeps the hidden panel out of the accessibility tree
            and the tab order. */}
        <aside className={panelClass} aria-label={`Summary: ${summary.title}`}>
            <button
              type="button"
              className={`${panelClass}-dismiss`}
              aria-label="Dismiss summary"
              onClick={() => {
                setDismissed(true);
                setHoverOpen(false);
                onSummaryDismiss?.();
              }}
            >
              <span className="material-symbols-rounded" aria-hidden="true">
                close
              </span>
            </button>

            <span className={`${panelClass}-meta`}>
              <span className={`${panelClass}-overline`}>{summary.overline ?? 'AI summary'}</span>
              {summary.caption && (
                <span className={`${panelClass}-caption`}>{summary.caption}</span>
              )}
            </span>

            <span className={`${panelClass}-title`}>{summary.title}</span>

            <span className={`${panelClass}-text`}>
              {phase === 'skeleton' ? (
                <Skeleton variant="text" lines={3} />
              ) : phase === 'typing' ? (
                /* An invisible ghost of the finished text sizes the
                   container, so the type-out never jumps the panel and a
                   short summary leaves no reserved space behind it. */
                <>
                  <span className={`${panelClass}-text-ghost`} aria-hidden="true">
                    {summary.text}
                  </span>
                  <span className={`${panelClass}-text-reveal`}>
                    <StreamingText
                      text={summary.text}
                      streaming={false}
                      cursor
                      drainMs={MOTION_SUMMARY_REVEAL_MS}
                      onRevealComplete={() => setPhase('cached')}
                    />
                  </span>
                </>
              ) : (
                summary.text
              )}
            </span>

            {/* The chips arrive under the finished summary, the way the
                chat's follow-ups do — showing them while the panel still
                "thinks" would give the staging away. */}
            {summary.suggestions && summary.suggestions.length > 0 && phase === 'cached' && (
              <span className={`${panelClass}-actions`}>
                <PromptSuggestions
                  layout="stack"
                  size="compact"
                  ariaLabel="Suggested prompts"
                  suggestions={summary.suggestions}
                  onValueChange={onSummarySuggestion}
                />
              </span>
            )}
          </aside>
      </div>
    );
  },
);

AiButton.displayName = 'AiButton';
